        setops: list[exp.SetOperation] = []

        while this:
            setop = self.parse_set_operation(this)
            if not setop:
                break
            setops.append(setop)
            this = setop

        if setops:
            last_operand = setops[-1].expression
            this = self._group_set_operations(this, setops)

            if self.MODIFIERS_ATTACHED_TO_SET_OP:
                if last_operand:
                    for arg in self.SET_OP_MODIFIERS:
                        expr = last_operand.args.get(arg)
                        if expr and not (arg == "limit" and expr.meta.get("top")):
                            last_operand.set(arg, None)
                            this.set(arg, expr)

