                if self._curr.token_type in (TokenType.LIMIT, TokenType.FETCH):
                    this = self._parse_query_modifiers(this)
            elif last_operand and last_operand.parent is not this:
                for arg in self.SET_OP_OUTER_MODIFIERS:
                    if expr := last_operand.args.get(arg):
                        last_operand.set(arg, None)
                        this.set(arg, expr)

        return this

    def _group_set_operations(
        self, this: exp.Expr | None, setops: list[exp.SetOperation]
    ) -> exp.Expr | None:
        """
        Rearranges a flat, left-associative chain of set operations so that the grouping
        implied by the dialect's precedence rules is explicit, using parenthesized operands.
        """
        if self.dialect.INTERSECT_BINDS_TIGHTER:
            # Runs of INTERSECT are grouped first, and each run is then combined left to right
            # with the UNION / EXCEPT operators that separate them
            result: exp.Expr | None = None
            pending: exp.SetOperation | None = None
            run: exp.Expr | None = setops[0].this
            is_chain = False

            for setop in setops:
                if isinstance(setop, exp.Intersect):
                    setop.set("this", run)
                    run = setop
                    is_chain = True
                else:
                    result = self._close_set_operation_run(result, pending, run, is_chain)
                    pending = setop
                    run = setop.expression
                    is_chain = False

            return self._close_set_operation_run(result, pending, run, is_chain)

        # All operators have the same precedence, so an INTERSECT whose left side is a UNION or
        # EXCEPT chain needs to wrap it, in order to survive generation by other dialects
        result = setops[0].this
        for setop in setops:
            if isinstance(setop, exp.Intersect) and isinstance(result, exp.SetOperation):
                if not isinstance(result, exp.Intersect):
                    result = exp.Subquery(this=result)
            setop.set("this", result)
            result = setop

        return result

    def _close_set_operation_run(
        self,
        result: exp.Expr | None,
        pending: exp.SetOperation | None,
        run: exp.Expr | None,
        is_chain: bool,
    ) -> exp.Expr | None:
        if pending is None:
            return run

        if is_chain:
            run = exp.Subquery(this=run)

        pending.set("this", result)
        pending.set("expression", run)
        return pending

